CREATE OR REPLACE FUNCTION public.create_reply_notification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  parent_user_id UUID;
BEGIN
  -- Only create notification for replies (not top-level comments)
  IF NEW.parent_comment_id IS NOT NULL THEN
    -- Get the user_id of the parent comment
    SELECT user_id INTO parent_user_id
    FROM repository_comments
    WHERE id = NEW.parent_comment_id;
    
    -- Don't notify if replying to own comment
    IF parent_user_id != NEW.user_id THEN
      INSERT INTO repository_notifications (user_id, type, repo_full_name, comment_id, from_user_id)
      VALUES (parent_user_id, 'comment_reply', NEW.repo_full_name, NEW.id, NEW.user_id);
    END IF;
  END IF;
  
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_user_activity_stats(p_user_id uuid, p_days integer DEFAULT 365)
 RETURNS TABLE(total_activities bigint, avg_per_day numeric, current_streak integer, max_streak integer, active_days bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_current_streak INTEGER := 0;
  v_max_streak INTEGER := 0;
  v_temp_streak INTEGER := 0;
  v_date DATE;
  v_has_activity BOOLEAN;
BEGIN
  -- Get basic stats
  SELECT 
    COALESCE(SUM(activity_count), 0),
    COALESCE(ROUND(SUM(activity_count)::NUMERIC / NULLIF(p_days, 0), 1), 0),
    COUNT(DISTINCT activity_date)
  INTO 
    total_activities,
    avg_per_day,
    active_days
  FROM public.activity_logs
  WHERE user_id = p_user_id
    AND activity_date >= CURRENT_DATE - p_days;

  -- Calculate current streak (from today backwards)
  v_current_streak := 0;
  FOR i IN 0..p_days LOOP
    v_date := CURRENT_DATE - i;
    
    SELECT EXISTS(
      SELECT 1 
      FROM public.activity_logs 
      WHERE user_id = p_user_id 
        AND activity_date = v_date
    ) INTO v_has_activity;
    
    IF v_has_activity THEN
      v_current_streak := v_current_streak + 1;
    ELSE
      EXIT;
    END IF;
  END LOOP;

  -- Calculate max streak
  v_temp_streak := 0;
  v_max_streak := 0;
  FOR i IN 0..p_days LOOP
    v_date := CURRENT_DATE - i;
    
    SELECT EXISTS(
      SELECT 1 
      FROM public.activity_logs 
      WHERE user_id = p_user_id 
        AND activity_date = v_date
    ) INTO v_has_activity;
    
    IF v_has_activity THEN
      v_temp_streak := v_temp_streak + 1;
      IF v_temp_streak > v_max_streak THEN
        v_max_streak := v_temp_streak;
      END IF;
    ELSE
      v_temp_streak := 0;
    END IF;
  END LOOP;

  current_streak := v_current_streak;
  max_streak := v_max_streak;

  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_notification_read()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.is_read = true AND OLD.is_read = false THEN
        NEW.read_at = now();
    END IF;
    RETURN NEW;
END;
$function$

